type Todo = { id: i32, title: String, note?: String, done: bool }

fn draft_of(t: Todo) -> Todo { { ...t, note: "x" } }        // 期待する型が note?: String なので Some として受ける
fn cleared(t: Todo) -> Todo { { ...t, note: None } }        // JS: { ...t, note: undefined }

pub fn TodoRow({ todo, subtitle }: { todo: Todo, subtitle?: String }) -> Jsx {
  <li>
    {todo.title}
    {subtitle.map((s) => <small>{s}</small>)}            // Option<Jsx> を子に置ける。None は undefined になり、何も描かない
  </li>
}

pub fn label(t: Todo) -> String { t.note ?? "(no note)" }   // 右辺は None のときだけ評価する

pub fn Demo() -> Jsx { <ul><TodoRow todo={{ id: 0, title: "a", done: false }} subtitle="hi" /></ul> }
// JS: _jsx(TodoRow, { todo: { id: 0, title: "a", done: false }, subtitle: "hi" })  省略した note はキーを書かない
